import{_ as i,c as l,o as a,ah as e}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"正辭第十八","description":"杭氏易學 - 正辭第十八","frontmatter":{"title":"正辭第十八","description":"杭氏易學 - 正辭第十八"},"headers":[],"relativePath":"classics/hangshi/019.md","filePath":"classics/hangshi/019.md"}'),t={name:"classics/hangshi/019.md"};function s(r,p,n,c,_,o){return a(),l("div",null,[...p[0]||(p[0]=[e('<h1 id="正辭第十八" tabindex="-1">正辭第十八 <a class="header-anchor" href="#正辭第十八" aria-label="Permalink to “正辭第十八”">​</a></h1><p>《系傳》曰：“開而當名辨物，正言斷辭，則備矣。”故斷辭必先正言，正言必先辨物，辨物必先當名，名稱其實為當。名而當，則舉其名而物之大小情偽畢見矣。盈天地之間唯萬物，物各有其名，不能悉舉也。而《易》以《彖》、《象》、《爻》三者賅之，以三者舉其綱，而八卦六十四卦之名無不當，天地萬物胥可以名辨而別之。擬之後言，議之後動，而正言斷辭如視之掌矣。</p><p>顧不曰名，而概之以辭者，以《易》之所謂名，皆假名也。本無是物，而以象擬之。無是事，而以象言之。聖人設卦觀象，大而天地風雷，小而蟲鳥沙石，常則家人夫婦，怪則鬼車狐尾，皆假設此物比事，擬諸其形容，象其物宜，以明陰陽造化之妙用，而定人事之吉凶，故曰“繫辭”。辭焉者，各指其所之。有名辭也，有動辭也，有狀辭及介辭也，未嘗不可辨而晰之。第《易》道通變，其辭亦通變。有名辭而兼作動辭者，有動辭或兼狀辭之用者，如乾為木果，變巽則為不果。雷風相薄，而《繫辭》曰“茅之為物薄”。用一字而面面皆通，立一義皆頭頭是道。苟泥其辭而不察其象，察其象而不究其理，而繫辭之意終不可得。故必欲執一例以求之，則六十四卦皆死物矣。然則《易》之辭果無例可求乎？曰是在學者之神而明之，變而通之，無定之中，亦未始無一定之軌則可循。旨遠而辭隱，是在虛其心以求之，潛其心以會之而已。</p><p>《易》以道陰陽，故《傳》曰“一陰一陽之謂道”，又曰“立天之道，曰陰與陽”，舉天道而地道人道一以貫之矣。蓋剛柔仁義，亦無非一陰一陽之對待也。而六十四卦，而三百八十四爻，亦無非一陰一陽之對待也。故孔子於乾之初九曰“陽在下也”，於坤之初六曰“陰始凝也”，即為六十四卦三百八十四爻之舉例發凡，以明九之皆為陽，六之皆為陰。而《易》之《彖》、《象》十翼，均無非闡明陰變化作用，故先以對待之辭舉例如下。</p><p>動靜</p><p>乾“其靜也專，其動也直”，坤“其靜也翕，其動也闢”。動靜二字，直陰陽所由判，吉凶所由生，如水火互相為根。昔儒“陽動陰靜”之說，與太極動則為陽，靜則為陰之說，辭意似均未圓滿。陰陽如環無端，動靜亦如是也。</p><p>剛柔</p><p>《雜卦傳》“乾剛坤柔”，《說卦》曰“立地之道，曰柔與剛”，又曰“分陰分陽，迭用柔剛”，《系傳》“動靜有常，剛柔斷矣”，又曰“剛柔相摩”，又曰“剛柔相推，而生變化”，又曰“剛柔者晝夜之象也”，又曰“剛柔相推，變在其中矣”，又曰“剛柔者立本者也”，又曰“知柔知剛，萬夫之望”，又曰“上下無常，剛柔相易”又曰“剛柔雜居，而吉凶可見矣”，又曰“柔之為道不利，遠者其要無咎，其用柔中也。其柔其危其剛勝耶？”《周易》用剛，故曰“乾元用九，而天下治”。陽剛而陰柔，亦猶以陽統陰之義也。齊小大者存乎卦，陽大陰小，在八卦，坤小乾大，艮止巽齊，是為大與小不齊也。止而齊之，則大通於小，小進於大。裒多益寡，故泰否“小往大來”，與“復小臨大”，皆無非於萬有之不平者，而求其平，此《易》之微旨也。</p><p>《否-上九》“先否後喜”，蠱之“先甲後甲”，巽之“先庚後庚”，說者謂陽先陰後，陰宜後而順承陽。不順陽而先陽，則迷而失道。陽宜先陰，不先而反後，則失時失道，此一義也。自康節之學行，又有先天后天之說。言漢學者，攻擊之不遺餘力，然其數理精確，且皆出於天然，不加造作。而按之於經，胥有徵驗。近儒端木鶴田，作《周易指》，以先後天說《易》，逐爻推尋，如按圖索驥，字字吻合，尤為發前人所未發。較虞氏之旁通，更為直捷而少枝節也。</p><p>順逆</p><p>《坤-彖傳》曰“乃順承天”，又曰“後順得常”。《說卦》曰：“坤順也。”坤順承天，則天逆行，順逆交，錯而四時錯行。日月代明，而天地之道乃成。陽在陽中陽順行，而陽在陰中則逆行。陰在陰中陰順行，而陰在陽中則逆行。大明生於東，月生於西。日行東陸則為秋，日行西陸則為春，陰陽非交互不能成其用也。五行順行則生，逆行則克。有生無克，不能成物。有逆無順，不能生物。故逆生順死，其旨甚微。故曰“《易》逆數也”。</p><p>內外</p><p>《泰*傳》曰：“內陽而外陰，內健而外順，內君子而外小人。”《否-傳》曰：“內陰而外陽，內柔而外剛，內小人而外君子。”《明夷-傳》曰：“內文明而外柔順。”《家人-傳》曰：“男正位乎外，女正位乎內。”此以卦之上卦為外，下卦為內也。《雜卦傳》曰：“睽外也，家人內也。”言虞氏學者，以家人與睽分屬內外，則以旁通之兩卦而言。睽與蹇旁通，睽為外則蹇為內。家人與解旁通，家人為內則解為外。內其故也，外其新也。內其躬也，外其鄰也。蓋以五已正位者為內，五未正位者為外。無妄，剛自外來而為主於內，亦以無妄之九五自睽來。以明睽為外，既成無妄，則為主於內，以明無妄為內也。無妄五剛，睽五柔，此兼剛柔言內外也。《周易指》：“以凡言內者，皆因家人。言外者，皆因睽。”《坤-文言》：“直其正也，方其義也。君子敬以直內，義以方外。”亦取象家人與睽，即《易》言內外之凡例也。</p><p>往來</p><p>《系傳》曰：“往者屈也，來者信也。一往一來謂之變，往來不窮謂之通。”蓋陰陽以往來始成其變化，故日往月來，月往日來，大往小來，小往大來，往來而得其道則吉，失道則兇。卦例：由內而之外為往，由外而之內為來。八卦、六十四卦，皆此一往一來，以經綸運轉而不窮。八卦，乾圓往者屈，而坤方來者信。由乾圓往者，東南西北也。由坤方來者，西南東北也。六十四卦，則乾往坤來，屯往蒙來，以迄於既濟未濟，皆此往來也。此以卦言者也。其以爻言者，如“往得中也”，“往有功也”，“剛來而得中也”，“剛來而文柔也”，要皆指二五而言。詳於虞氏之旁通。</p><p>上下</p><p>上者，丄也。下者，丅也。上天下地，而中為人。故《易》經文言“上下”者，僅小過一卦，曰“小過亨利貞，不宜上宜下。大吉”。《傳》曰：“不宜上宜下，大吉，上逆而下順也。”蓋《易》者，聖人寡過之書。五十學《易》，可以無大過，而小過或不免也。小過之中二爻，正當六畫卦之人爻，所謂“立人之道，曰仁與義”者此也。故乾之三四兩爻 【小過爻也】 ，特著無咎。“無咎者，善補過也。”惟明乎此上下，則得乎中，而過可免矣。故《乾-文言》曰：“本乎天者親上，本乎地者親下。”於九三、九四，皆曰“上不在天，下不在田”，又曰“上下無常”。《雜卦傳》曰“離上而坎下也”，《益-彖傳》曰“損上益下”，《損-彖傳》曰“損下益上”，皆以損益得宜，以蘄合乾坤坎離之中，而上下交泰 【乾坤交成泰】 ，以成既濟者也。故明小過之上下，而六十四卦之上下，均可以言矣。</p><p>方圓</p><p>《說卦》“乾為圓”，《荀九家》“坤為方”，《系傳》“蓍之德，圓而神。卦之德，方以知”，《坤-六二》“直方大”，《系傳》又曰“無窮盡，無方體”，又曰“是故神無方而《易》無體”。蓋圓者，神也。方者，體也。乾為天為圓，無體故無方。坤為地，有體故有方。舊說“圓象天，方法地”，簡言之，則曰“天圓地方”，“奇圓耦方”。近人知地球之為渾圓而非方也，於是曲為之說曰“天圓地方”，言其德非言其體也。而不知《易》之所謂“圓而神，方以知”者，明明指蓍與卦，未嘗謂天之德圓與地之德方也。而乾圓坤方，則確不可易。第所謂方者，即西南東北之方，非謂地體之為立方形也，又何必曲為之解哉！圓無盡而方有盡，故度圓者必以方。玩“乾其靜也專，其動也直”，“坤其靜也翕，其動也闢”二語，則方圓之妙用已闡發無遺。近世幾何形學之界說，皆不能出其範圍矣。</p><p>進退</p><p>《系傳》曰：“變化者，進退之象也。”剛柔相推而生變化，故進退與往來不同。《序卦傳》曰：“晉者進也，遁者退也。”又曰：“漸者進也。”《雜卦傳》雲：“遁則退也，需不進也。”《說卦傳》曰：“巽為進退。”《巽-初六》：“進退利武人之貞。”《觀-六三》曰：“觀我生進退。”《乾-九四-文言傳》曰：“進退無恆。”上九：“知進而不知退。”蓋陽進陰退，由內而之外進也，由上而之下退也。進而當，則為得為吉。進而不當，則為失為兇。是皆由陰陽變化而生，故曰“變化者，進退之象也”。</p><p>遠近</p><p>《系傳》曰：“遠近相取，而悔吝生。”近與邇同義。《系傳》言“遠近”者三，言“遠邇”者二。《震-彖》“驚遠而懼邇也”，《蒙-六四》“獨遠實也”，《剝-六四》“切近災也”。餘或單言遠單言近者，要皆指爻位而言。蓋爻之相得者宜近，不相得者不宜近。故《傳》又重言以申明之曰：“凡《易》之情近而不相得，則兇。或害之，悔且吝。”又曰：“二與四同功而異位。二多譽，四多懼，近也。柔之為道不利，遠者其要無咎，其用柔中也。”故論爻之遠近以明吉凶，有就本卦之爻位論者，有就變卦之爻位論者。本卦之爻位，以承乘、與比、相應、相合者，為近。否則為遠。變卦之爻位，則他卦之爻一變而即得者為近，須再變三變而始到本卦者為遠。凡卦爻之言遠近者，皆含此二義，不可不審也。</p><p>新舊</p><p>《易》用九用六。九六變也。變則新，故《系傳》曰“日新之謂盛德”，《大畜-彖》曰“剛健篤實輝光，日新其德”。鼎“取新也”，革“去故也”，隨“無故也”。故六舊之義也。《訟-六三》曰“食舊德”，《井-初六》曰“舊井無禽”。食舊德，則貞厲。“舊井無禽”，則不食，皆去舊而宜從新者也。此外如噬嗑之“噬臘肉”，大壯之“壯於前趾”，乾為“老馬”，曰“老”，曰“前”，曰“臘”，亦皆舊之義也。遠近以位言，新舊以時言，變通者趣時者也。趣時則日新，是以《雜卦》曰“大畜時也”。</p><p>死生</p><p>“生生之謂《易》”，《易》之道本生生而不已者也。然不能盡其道，即不能有生而無死。《系傳》曰：“原始反終，故知死生之說。”故《檀弓》曰：“君子曰終，小人曰死。”終則有始，而死則不能復生，此君子小人之別也。經之稱“生”者二卦：觀之“觀我生”，“觀其生”；大過之“枯楊生稊”，“枯楊生華”是也。稱“死”者二卦：離之“突如其來如，焚如死如棄如”，豫之“貞疾恆不死”是也。蓋乾為大生，坤為廣生。大生故“資始”，廣生故“資生”。而所以資始而資生者，實惟“大哉乾元，坤順承乾”，坤元亦統於乾元。《文言》曰：“元者善之長。”於人為仁。元從二兒，仁亦從二兒，於乾坤二象為二五之中。豫之“恆不死”，《象》曰“中未亡也”。困之六三以陰乘陽，以柔掩剛，是賊仁害義，昧其天良者也。故《系傳》曰“死期將至”。中未亡者，終則有始。亡其中，則生亦幸。所謂行屍走肉，待死而已。</p><p>有無</p><p>《易》以有立教者也。《易》有太極，是生兩儀。四象八卦，而定吉凶以生大業。故《序卦-上傳》曰“有天地然後萬物生焉”，《序卦-下傳》曰“有天地然後有萬物，有萬物然後有男女，有男女然後有夫婦，有夫婦然後有父子，有父子然後有君臣，有君臣然後有上下，有上下然後禮義有所錯”，皆以明有之義也。《下經》首鹹，《序卦》不言鹹，鹹無也。不言無而言有，此即《易》之開宗明義也。然《序卦》不言鹹，而《系下傳》於“憧憧往來朋從爾思”一爻，推闡“往來屈信”之理。而以窮神知化歸之，聖人之意亦可見矣。《傳》曰“書不盡言，言不盡意”，故聖人立象以盡意。</p><p>書所未言者，自當求之於言外之意。意有未得者，當索之於所立之象。自象學不明，或空言以說理，或執經而忘象。更以門戶派別之故，互相攻擊，入主出奴，是丹非素，而《易》道遂晦盲終古矣。須知《易》固以有立教，然有無實相對待，言有而無可見。孔子猶慮後人之以辭害意，而不能通也，故特表鹹之九四一爻，以明同歸殊途之旨。蓋立教為中人以下說法，而精義入神之道，則非言所能盡。而立象盡意，是在中人以上自悟之耳。故卦象乾為無，自無而有，由坎出震，而生生之道乃循環而不已。鹹為無，君子以虛受人，而窮神知化之學，始日進而不窮。乾之無，天極也。鹹之無，人極也。通天地人謂之儒，貫通三才而返本窮源，則仍必以契合乎天為止境。故六十四卦統歸納於一乾，而“大哉乾元乃統天”。明乎此，則後儒斷斷於有無之界者，均可渙然而冰釋矣。</p><p>此外如尊卑、貴賤、幽明、始終、多寡、善惡、利害、窮通、遲速、安危、治亂、存亡、寒暑、晝夜、燥溼、俯仰、平陂、虛實、闢翕、分合、輕重、微顯、厚薄，與夫天地、日月、男女、禮樂、仁義，凡相對待者，皆一陽一陰之義，未可悉舉。所謂“因貳以濟民行，以明得夫之報”者也。孔子《十翼》以“乾剛坤柔”終篇，取五十六卦一一以對待明義，而又於《系傳》特著其例，曰“乾坤為《易》之門”。得其門而入者，可知所自矣。</p><p>對待之辭曰“對辭”，而非對待者曰“單辭”。單辭者，凡以為對辭之用也。且單辭亦往往含有二義，辭繁非可悉舉，茲略舉如左。</p><p>中</p><p>《易》道尚中。凡過乎中者，大過小過，皆變化之進退之以求合乎中。蓋人為天地之中，故以中立人之極，而陰陽剛柔始各得其正，而無所偏倚，而後盡《易》之能事也。中有虛實二義：實者有形，以所處之位言之，如卦之二五兩爻是也。虛者無質，以至當之主義言之，如卦之主爻是也。蓋一卦之主爻，有時在二五，有時不在二五。如比以五陽為主，同人以五陰為主者，主爻在爻位之中者也。復以初陽為主，小畜以四陰為主者，主爻不在二五之中者也。故曰“中無定在”。以二五為中者，如天平倚點居正中，重心與中心，同居一位。不在二五之中者，如秤桿之倚點，視重點力點比例之差，求得其力點與倚點距。重點與倚點距，相等之所在，即中心之所在也。孟子曰“子莫執中”，執中為近之。執中無權，猶執一也。蓋即如天平之中也。《易》道之中，即孟子所謂權，可以前後移動，以求合力點重點與倚點相等之中者也。</p><p>時</p><p>孔子之道曰“時”曰“中”，後人稱為“時中之聖”，要皆推本於《易》道。於《蒙-彖》贊曰：“蒙亨，以亨行時中也。”蒙以養正，聖功之始。然《易經》之言時者，惟《歸妹-九四》曰“遲歸有時”，他無見也。孔子贊《易》，始於時字多所發揮，而於《系傳》總揭其義曰“變通配四時”，又曰“變通莫大乎四時”，又曰“變通者趣時者也”。於《豐-傳》曰“天地盈虛與時消息”。合而觀之，孔子言“時”之旨趣，具可見矣。故於乾之九三日“與時偕行”，於上九曰“與時偕極”。損益皆曰“與時偕行”，隨曰“隨時”，節曰“失時”，革曰“明時”，無妄曰“對時”，睽蹇皆曰“時用”，豫姤旅皆曰“時義”，坤曰“時發”，賁曰“時變”，而於《艮-彖傳》總揭其義曰：“時止則止，時行則行。動靜不失其時，其道光明。故君子進德修業欲及時也。”此可謂孔子於《易》獨得之秘，而為天下萬世指迷者也。</p><p>若以時論時，則亦含有二義：一曰有定之時。如天之四時，時有定候，非人之所能變更，是惟順承乎天，所謂後天而奉天時者也。一曰無定之時。如人事之有輕重緩急，而陰陽五行各有始有壯有究，或損或益，或行或止，所謂觀乎天文以察時變者也。故時有以盈虛消息言者，泰否剝復之類是也。有以事言者，訟師噬嗑頤之類是也。有以理言者，謙履鹹恆之類是也。有以象言者，井鼎之類是也。</p><p>位</p><p>《系傳》曰“卑高以陳，貴賤位矣”，又曰“列貴賤者存乎位”。《說卦傳》“天地定位”，“《易》六位而成章”，此皆指卦位與爻位而言也。《系傳》曰“危者安其位者也”，又曰“德薄而位尊”，此則由爻象而擬議之爵位之位也。故“位”字亦有此二義。帝出乎震，震東方也，至艮東北之卦也。此八卦之方位。卑高以陳，貴賤位矣，則上下卦 【即外卦內卦】 之位定。上卦為高，下卦為卑，貴宜卑而賤有高矣。列貴賤者存乎位，則卦爻二五，五貴而二賤。王弼謂中四爻有位，初上無位者，即此位也。《易》六位而成章，則分陰分陽，迭用柔剛。所謂陰陽之位，初三五為陽位，二四六為陰位。陽居陽，陰居陰，為當位。反之為不當位。位從立從人，所謂“立人之道曰仁與義”，故三畫卦與六畫卦，皆分天地人三位。而孔子贊《易》則專言人道，天位地位皆以人居之，必能合乎仁義之道，方能與天地參而無慚此位也。</p><p>德</p><p>《易》之言德，亦分二義：</p><p>一曰卦德。《繫辭》“雜物撰德”，又曰“陰陽合德，剛柔有體，以體天地之撰”，此卦德也。夫乾天下之至健也，德行恆易以知險。夫坤天下之至順也，德行恆簡以知陰。健順乾坤之德也。推之震動巽入，離麗坎陷，艮止兌說，皆其德也。而人用即謂之材。彖者材也，故亦謂之卦材。</p><p>一曰道德。《說卦》曰“和順於道德”，《系傳》曰“天地之大德日生”，又曰“以通神明之德”，又曰“默而成之不言而信存乎德行”，皆道德之德也。德有大小，必與位稱。無德而據位，謂之竊位。德薄而位尊，其形渥兇。《易》之興也，其於中古。去古已遠，降而言德。《繫辭下傳》七章之三陳九德，即孔子以《易》設教，而示人以立德之方也。</p><p>變</p><p>《系傳》曰“道有變動，故曰爻”，又曰“爻者言乎變者也”，又曰“一闔一闢謂之變”，又曰“剛柔相推而生變化，變化者進退之象也”，又曰“參伍以變，錯綜其數。通其變遂成天地之文，極其數遂定天下之象。非天下之至變，其孰能與於此”，又曰“《易》窮則變，變則通”，又曰“變而通之以盡利”，又曰“變動不居，周流六虛。上下無常，不可為典要，唯變所適”。繫辭之言變，詳且盡矣。蓋宇宙以變而久存，亦以變而日新。無時不變，無境不變。特其跡甚微，人自不知覺耳。</p><p>通</p><p>《易》窮則變，變則通。故“變通”二字，往往聯綴而言。《系傳》曰“一闔一闢謂之變，往來不窮謂之通”，又曰“化而裁之謂之變，推而行之謂之通”，又曰“變通配四時”，又曰“無思也，無為也，寂然不動，感而遂通天下之故”，又曰“唯深也，故能通天下之志”，又曰“通乎晝夜之道而知”，又曰“觀其會通以行其典禮”，又曰“體天地之撰以通神明之德”。合變通而觀之，而《易》之所以為《易》可見矣。而《序卦傳》曰“泰者通也。物不可以終通，故受之以否”，《雜卦傳》曰“井通而困相遇也”，《系傳》又曰“困窮而通”，《乾-文言》曰“六爻發揮旁通情也”，《坤-文言》曰“君子黃中通理”。合而觀之，而《易》可通矣。</p><p>當</p><p>適其可之謂當。凡變也通也，變而通之以盡利，無非由不當而變通之以求其當而已矣。止於至善，位之當也。當其可之謂時，時之當也。陽九陰六之位當矣，而時不相得，或情不相得，則仍有未當。故《象傳》有以當位之爻而言位不當者，如需之上六等類是也。變通之最大者，莫過於革。《革-彖傳》曰“革而當其悔乃亡”，而當之義可見矣。</p><p>交</p><p>易者交易也。非交無以為易，故交者《易》之妙用，亦不啻為《易》之代名辭也。《系傳》曰“君子安其身而後動，易其心而後語，定其交而後求”，又曰“無交而求，則民不與也”。蓋《易》以明道，而道在人。人在天地間，決不能離群而獨立也。近則男女夫婦父子，遠則君臣朋友，無不有所合也。有合則必有交。人在天地間，又不能絕物而自養也。小則日用飲食，大則養生送死，無不有所需也。有需則必有交。甲有所需於乙，乙有所需於甲，丙有求合於丁，丁有求合於丙，於是交相為需，交相為養，而人事以興。故《易》象以陰陽明之。陰交於陽，陽交於陰，大有之“無交害”，隨之“交有功”是也。《家人-傳》曰“交相愛也”，《睽-傳》曰“交孚無咎”，故必相愛相孚，而交之道始可久。天地交則泰，否則天地不交萬物不生，人道息矣。西人曰“互助”，惟《易》之“交”足以盡其義也。</p><p>幾</p><p>吉凶悔吝生乎動，而欲動未動之前，則為幾。《系傳》曰“知幾其神”，又曰“幾者動之微吉之先見者也”。《乾-九三》“終日乾乾夕惕若”，《文言》曰“知至至之可與幾也”。《屯-六三》曰“君子幾，不如舍，往吝”，《豫-六三》“介於石不終日”，《系傳》曰“見幾而作，寧用終日”。蓋乾九三為人爻之始，動靜所生，吉凶著焉。理欲之界，人禽判焉。孟子所謂“人之所以異於禽獸者幾希”，即此幾也。周子所謂“誠無為，幾善惡”，亦此幾也。復之初九“不遠復，毋祗悔”，孔子曰“顏氏之子，其庶幾乎”。故幾者，《易》道精微之所在。堯舜之心傳，曰：“人心惟危，道心惟微。”幾者，動之微，即此道心之微也。君子知幾，即在“不遠復”之“反覆其道”。故《文言》又曰“終日乾乾，反覆道也”。聖人丁寧告誡之意，亦可謂深切而著明矣。“夫《易》，聖人所以極深而研幾也。唯深也，故能通天下之志。唯幾也，故能成天下之務。”“幾事不密則害成”，是以“君子洗心退藏於密”。</p><p>至</p><p>《乾，彖傳》曰“大哉乾元”，《坤-彖傳》曰“至哉坤元”。大無限量，而至有際極。大也，至也，聖人贊《易》開始之第一字也。即此一字，已將乾坤全體之精神分量，概括無遺。並將乾坤兩卦之方式作用，分析明自。挈全《易》之綱領，洩造化之神秘。《系傳》曰：“《易》其至矣乎！”聖人之情見乎辭矣。大者何，由小以至大也。非至無由顯其大，非大無以極其至，故至亦有大義。家人、豐、渙，皆雲“王假”。假，大也，至也，皆坤之義也。《坤-初六》“履霜堅冰至”，履通謙，謙履相錯為臨遁，故《臨-六四》曰“至臨”。《坤-六四》“括囊”，括，亦至也。而《臨-彖》“至於八月有兇”，謂臨至遁也。由此至彼，必上有所承，故必須承乎乾元，始得止於至善，而為坤元，為至哉坤元，為至道，為至德。為至當不易，失其所承，則為失道，為迷。《復-上六》“迷復兇”，《傳》曰“至於十年不克徵”，故得道則曰“朋至 【解】 ”，失道則曰“寇至 【需】 ”，“朋至”則“得其友 【損】 ”，“寇至”則“傷之”者至矣 【益】 。履和而至 【履通謙，則陰陽和】 ，則非堅冰至，則積善必有餘慶。《系傳》曰：“勞謙，君子有終，吉。勞而不伐，有功而不德，厚之至也。”又曰：“藉之用茅，何咎之有？順之至也。”順與厚，皆坤德也。《文言》曰：“坤，至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎？順天而時行。”贊坤元無餘蘊矣。故《易》者，天下之至精，天下之至變，天下之至神。皆“至哉坤元”之至，故“不疾而速，不行而至”。</p><p>道</p><p>《說卦》曰：“昔者聖人之作《易》也，將以順性命之理。是以立天之道，曰陰與陽。立地之道，曰柔與剛。立人之道，曰仁與義。兼三才而兩之，故《易》六畫而成卦。分陰分陽，迭用柔剛。故《易》六位而成章。”《系傳》曰：“《易》之為書也，廣大悉備。有天道焉，有地道焉，有人道焉。兼三才而兩之，故六。六者，非它也，三才之道也。”又曰：“六爻之動，三極之道也。”此《易》道也。經之言“道”者四：《復-彖》曰“反覆其道”，《小畜-初九》曰“復自道”，《履-九四》曰“履道坦坦”，《隨-九四》曰“有孚在道，以明”，皆在《上經》，已將道字發揮淨盡，故《下經》不復贅言，以俟後人之觸類旁通而己。《傳》之言“道”者，曰“一陰一陽之謂道”，又曰“形而上者謂之道”。一陰一陽，變化往來，生生不已。以陽易陰，以陰易陽。乾道成男，坤道成女。陰陽反覆，一陰則反其道，一陽則復其道。故《復-彖》曰“反覆其道”，而《乾-九三-傳》亦日“反覆道也”。蓋陽以統陰，失其統則亢，亢則宜復。陰以承陽，失其承則迷，迷則宜反。反而不復，有陰而無陽，失道也。復而不反，有陽而無陰，亦失道也。“終日乾乾”之反覆，已復而欲其反也。“七日來複”之反覆，已反而欲其復也。反而不復，則其道窮。復而不反，則其道困。窮而知變，困而知通，通變隨時，損益得中，聖人之道也。知周乎萬物，而道濟天下，故不過，而《易》之道盡矣。</p><p>《傳》稱“得中道”五 【《離-六三》，《既濟-六二》，《夬-九二》，《蠱-九二》，《解-九二》】 ，“未失道”二 【《睽-九二》，《觀-六三》】 ，“其道窮”四 【《比-彖》，《蹇-彖》，《坤-上六》，《節-上六》】 ，“失道”三 【《坎-初六》、《上六》，《漸-九三》】 。由陽而陰，小人之道也，否也。由陰而陽，君子之道也，泰也。</p><p>命</p><p>有天地而後萬物生焉。萬物生於天地間者，莫不有命。蓋當其未生之前，本無是物也。乃忽而受氣成形，以有是物，形成於地，氣受於天，果孰使之然者？是則所謂命也。聖人設卦觀象，以明萬物之理，即以卦爻之變化往來，以示各有定命之所在。所謂設辭以明之也。《乾-彖》曰“乾道變化，各正性命”，可見命之所自來。即由乾道之變化，乾非坤無以變也，乾變坤化而乾道斯成。亦如男子必得婦生子，而始有父道也。故曰“一陰一陽之謂道”，分於道之謂命。經之稱“命”者六卦，《否-九四》“有命無咎”，《訟-九四》“復即命”，《革-九四》“改命吉”，《師-九二》“王三錫命”，上六“大君有命”，《泰-上六》“自邑告命”，《旅-六五》“終以譽命”，《傳》則曰“受命”，曰“順命”，曰“捨命”，曰“改命”，曰“申命”，曰“致命”，曰“凝命”。《易》之言命，略具於是矣。</p><p>蓋卦之變化，以正性命者，惟二五。乾二之坤五，其例也。二五之精，妙合而凝。故鼎曰“正位凝命”。命分於道，則道有變化，命亦有變通。受命者，得於天也。凝命者，全其體也。順命者，順其正也。捨命者，察其幾也。申命者，行其事也。致命者，遂其志也。改命者，革其故也。《詩》日：“維天之命，於穆不已。”窮理盡性以致於命，故曰“不知命無以為君子也”。孔子五十而知天命，其亦在學《易》以後乎？</p><p>理</p><p>《說文》：“理，治玉也。從玉里聲。”孔子系《易》於“理”字約分二義。《說卦》：“和順於道德而理於義。”此理字與和字相針對。和之義為合，理之義為分。分理之理，即治玉之理也。蓋物質之堅緻，而仍有條理可分者，無過於玉。堅則固，致則密。既固且密，則最不易分者，亦無過於玉。故以理為治玉之名，又廣其義為處分萬事。萬物之名，《易》道廣大，必分而析之，分而又分，析而又析，而後其精微者乃可得而見。亦如今之治化學者，於一物之體質，必分而析之，至於分無可分，析無可析，而所得者，即為此物之原質矣。故邵子之加一倍法，亦即分析法之還原者也。物理數理，皆有跡象可求，分而理之尚易。至理於義，則精微之至矣。其下文“窮理盡性以至於命”，此理字則為名詞，而非動詞，即指性分中所有之理。故鄭康成注《樂記》曰“理猶性也”，朱子注《中庸》曰“性即理也”，竟以理與性，相為轉註。然詳加研究，則終有未安。未可以大儒之說，遂附和之，而以為確當也。蓋性固有理，不能謂理即性，性即理。猶物各有理，不能謂物為理，謂理為物也。先儒此種訓詁，貽誤後學最多。是在學者之自有領悟，愈講解而糾纏愈甚矣。《坤-文言》曰“君子黃中通理”，與《乾-傳》“利貞者，性情也”，呼吸相通。苟於此領悟而有得焉，於明理之學，思過半矣。</p><p>性</p><p>分於道之謂命，分於命之謂性。心生為性，有生斯有命，有命斯有性，性命恆相聯屬。故《易》言命而不言性。孔子贊《易》，則曰“乾道變化，各正性命”，又曰“窮理盡性以至於命”，又曰“一陰一陽之謂道。繼之者善也，成之者性也”。言性之本源，可謂明白曉暢矣。後之言性者，約分三類：孟子，言性善；荀子，言性惡；告子，言性無善無不善。各明一義。性善之說，於立教為宜，故後世多宗之。其實曰善曰惡，已為性之所見端，未可謂之性也。告子無善無不善之說，殊未可厚非。孔子曰“性相近，習相遠”，亦此意也。宋儒因迴護孟子之說，於是創為義理之性，氣質之性，以分別善惡。謂生而善者，義理之性。習而惡者，氣質之性。益支離而不可通矣。</p><p>情</p><p>情者，性之動也。所謂人生而靜，天之性也。感於物而動，性之慾也。故性與情亦恆相聯屬。《易》言欲而不言情。孔子贊《易》，曰“利貞者，性情也”。《白虎通》曰：“性者，陽之施。情者，陰之化也。”《論衡》曰：“性生於陽，情生於陰。”《說文》：“性，人之陽氣，性善者也。情，人之陰氣，有欲者也。”皆性情並舉。性貞於誠，而情則有誠有偽。《繫辭》曰“設卦以盡情偽”，又曰“爻彖以情言”，又曰“吉凶以情遷。凡《易》之情近而不相得，則兇或害之悔且吝”又曰“六爻發揮，旁通情也”。觀旁通而情可見矣。</p><p>教</p><p>教以立人，道以立己，己立立人。故《易》之為書，無非道也，無非教也。卦之言教者三：坎“習教事”，臨“教思無窮”，觀“觀民設教”，而要以“蒙養”為立教之始。孔子更廣其義於漸，曰“居賢德善俗”。於蠱曰“振民育德”。於無妄曰“茂對時育萬物”。於是今世謂之文明教育之事業，而《易》無不備舉矣。而其博大精深之教義，則尚非今世物質文明之教育家，耳目思想所能及。當於卦爻內詳論之，茲未遑悉舉也。</p><p>用</p><p>《易》者，用世之書也。故以有立教，亦以用立教，亦即以中立教。有貴乎能用，有而不能用，則與無等耳。然非無不能明有之用，非用無以盡有之功，非中無以盡用之妙，故曰“有”，曰“用”，曰“中”。此《易》之界說也。必明此界說，而後《易》可得而言。《易》六十四卦，無一非用，而以乾坤用九用六發其凡。用六而曰以大終，則六亦九之用，故以乾元用九而天下治，以竟《易》之全功。《乾-九二》“庸言”“庸行”，言行君子之所以動天地也。而曰“庸”者，庸者用也，明用之非中不立也。</p><p>以</p><p>以，用也。孔子傳《易》，以明大用，於六十四卦之《象傳》明之。“天行健，君子以自強不息”。“地勢坤，君子以厚德載物”。六十四卦皆此以一字挈其綱，即“五十以學《易》”之以，亦即“以《易》傳教”本旨之所在也。蓋《彖傳》者，釋內外兩卦之用也。《象傳》則取兩卦之中，合上下之義而貫串之。兩卦之中者何？即三四兩爻，所謂中爻所謂人爻者是也。故曰“若夫雜物撰德，辨是與非，則非其中爻不備”。而二四三五同功，三四於六爻為人位，“立人之道”立於此。孔子之六十四“以”字，亦發明於此。明乎此，則庶乎可盡《易》之用。雖吉凶有命，而悔吝可免矣。故《易》於乾之九三九四兩爻，特著曰“無咎”。</p><p>之</p><p>之者，《易》之用也。爻有變動，故曰之。“辭也者各指其所之”，有所之而吉凶見焉。之字作屮。屮者一生三也。《易》者，一陰一陽。動有所之，而用生焉，則二生三也。故曰“一陰一陽之謂道”。之而當，則得道。之而不當，則失道。《無妄-傳》曰：“無妄之往，何之矣。”何之則道窮，是以君子慎其所之。</p><p>孚</p><p>舊說“孚，信也”。坎為信。凡卦言“有孚”，皆指坎，似是而實非也。孚果指坎，何以中孚無坎象？孚固有信之一義，然信字不足以盡孚也。孚從爪，從子，象鳥以爪抱子。鳥子為卵，爪子以象抱卵，有化育之意。中孚卦象，實以巽五兌十，乃五十五數之中，於五行為土。土主化物，故曰中孚。其曰“有孚”者，“有”謂大有。火天大有，離也。孚，則指坎。坎離居南北之位，合乾坤之中，維中能孚，故曰“有孚”。有則大，孚則化，“有孚”者，即《中庸》所謂“大德敦化”也。凡《易》之道，一陰一陽，必陽孚於陰，而陰孚於陽，而後陰陽和，而成化育之功。人品有君子小人，泰、否，君子小人之相消長者也。遁曰“君子吉，小人否”，觀曰“小人無咎，君子吝”。必君子能孚小人，則小人亦能化為君子。所謂“有孚顒若”，下觀而化，則先否後喜，天下受福矣。若不能用觀，則成大壯。義非不正，理非不直也。而剛以反動，小人用壯，君子用罔。羝羊觸藩，天下被其禍矣。乾元用九，必有孚而始致其用。故孚有信義，有化義，有容義，又有合義，有感義。所謂精義入神之用，以孚字盡之矣。非統全《易》而詳察之，又烏知其妙哉！</p><p>以上單辭，略舉一隅，可見經傳字無虛設。或一字而含數義，或數卦合用一字，無不脈絡貫通。潛心體玩，均有線索可尋。此外有字以類從，因意義相同，而互見於各卦而相貫串者，可謂之類辭，如則法律一類也，克伐徵一類也，速疾遇一類也，需繻須濡一類也，怠緩徐慢裕一類也。凡同乎此者，皆以義相類者也。如弟娣娣涕一類也，頄仇九一類也，輪綸一類也。凡同乎此者，皆以形聲相類者也。相類之字，於卦爻之變通意義，皆有關係，均可互相印證者也。其單辭之外，更又綴屬一字，或二字，或三四五字，以成一名辭，或成一句者，可謂之類句。如由頤、由豫；甘節、甘臨；頻復、頻巽；艮其腓、鹹其腓；困於酒食、需於酒食；我心不快、其心不快；同人，先號咷而後笑；旅人，先笑而後號咷之類，亦無不互相聯貫。如密雲不雨、帝乙歸妹、用拯馬壯吉、不富於其鄰，完全相同之一句，或二句，分見於兩卦或三卦者，則更為顯而易見。具詳於焦理堂氏之《易通釋》，茲不贅述也 【《易通釋》偏於旁通之正立言。有未可盡通化學者，以意逆之，勿以其辭雲意也可。】 。</p><p>舉單辭、對辭、類辭、類句，經傳之概略，已可見矣。而正言斷辭，尚有數例，更舉如左。</p><p>稱號</p><p>號者，名也。稱其名使與實相稱，亦當名辨物之意也。孟長卿曰：“周人五號，帝，天稱，一也。王，美稱，二也。天子，爵號，三也。大君者，興盛行異，四也。大人者，聖明德備，五也。”</p><p>以上五者，皆經之特稱。孔子贊《易》，更廣其義。</p><p>曰“先王”。豫，“先王以作樂崇德”。</p><p>曰“後”。泰，“後以裁成輔相之道”。</p><p>經稱爵號，王之下有三：</p><ul><li><p>曰“公”。大有，“公用享於天子”。解上六，“公用射隼”。益六三，“告公用圭”。六四，“告公從”。鼎九四，“覆公餗”。</p></li><li><p>曰“侯”。屯，“利建侯”。豫，“利建侯”。晉，“康侯”。</p></li><li><p>曰“子”。明夷，“箕子之明夷”。鼎，“得妾以其子”。</p></li></ul><p>言公、候、子而不及伯、男。或曰：“此殷制也。文王演《易》於紂之世，故從殷制。”</p><p>正名之稱有六：</p><ul><li><p>曰“大人”。一人為大。孟子日：“大人者，不失其赤子之心者也。”《文言》“與天地合其德”一節，孔子贊大人也至矣。</p></li><li><p>曰“君子”。乾為君，震為子。乾震為無妄，君子者。無妄之稱</p></li><li><p>曰“小人”。天大，地大，人亦大。與天地參，故大。違反天地之道，則曰小人。</p></li><li><p>曰“惡人”。睽“見惡人”，人而見惡於人，曰惡人。於象，離為惡人。</p></li><li><p>曰“寇”。寇者悖逆之詞。於象，坎為寇。</p></li><li><p>曰“匪人”。匪同非。“比之匪人”，“否之匪人”，失人道，故曰“匪人”。孟子曰：“無惻隱之心，非人也。無羞惡之心，非人也。無辭讓之心，非人也。無是非之心，非人也。”</p></li></ul><p>孔子贊《易》，更廣其義。</p><p>曰“聖人”，曰“賢人”，曰“盜”，亦曰“暴客”，日“吉人”，曰“躁人”，曰“誣善之人”。</p><p>名當而辭可斷矣。爻有等，故曰“物”。辨物當名，名不等也。正言，言不等也。故斷辭亦不等。兇至吉為七等：兇，厲，悔，吝，無咎，無不利，吉。</p><p>兇不若厲，厲不若悔，悔不若吝，吝不若無咎，無咎不若無不利，無不利不若吉。</p>',93)])])}const m=i(t,[["render",s]]);export{h as __pageData,m as default};
